export default async function install(app){const FeatureLayer=await app.import("esri/layers/FeatureLayer");const mount=app.getMount("capacity-site-details");const source=new FeatureLayer({url:app.config.serviceUrl,outFields:["*"]});await source.load();const result=await source.queryFeatures({where:"1=1",outFields:["*"],returnGeometry:false});const fields=source.fields||[];const alias=new Map(fields.map(f=>[f.name,f.alias||f.name]));const base=n=>String(n||"").replace(/\s*\[[^\]]+\]\s*$/,"").trim();const records=result.features.map(f=>f.attributes);const empty=document.createElement("p");empty.textContent="Choose Additional information from a site popup to inspect every available source attribute.";Object.assign(empty.style,{margin:"0",fontSize:"0.85rem",lineHeight:"1.45",color:"var(--calcite-color-text-2)"});mount.replaceChildren(empty);const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));const openPanel=()=>{const aside=document.querySelector("#app-region-left");if(!aside)return;const toggle=aside.querySelector(":scope > h2 calcite-action");const collapsed=aside.hasAttribute("collapsed")||aside.classList.contains("collapsed")||getComputedStyle(aside).width==="0px";if(collapsed&&toggle)toggle.click();else if(toggle&&aside.getBoundingClientRect().width<80)toggle.click()};const render=event=>{const name=String(event.detail?.name||"");const matches=records.filter(a=>String(a.Name)===name||base(a.Name)===name);const wrap=document.createElement("div");Object.assign(wrap.style,{display:"grid",gap:"14px"});const intro=document.createElement("p");intro.innerHTML=`<strong>${esc(name||"Site details")}</strong><br><span style="color:var(--calcite-color-text-2)">${matches.length} source record${matches.length===1?"":"s"}</span>`;intro.style.margin="0";wrap.append(intro);if(!matches.length){const none=document.createElement("p");none.textContent="No matching source record was found.";wrap.append(none)}for(const [index,a] of matches.entries()){const section=document.createElement("section");const heading=document.createElement("h3");heading.textContent=matches.length>1?`Record ${index+1}: ${a.Name}`:String(a.Name||"Attributes");Object.assign(heading.style,{fontSize:"0.95rem",margin:"0 0 8px"});const table=document.createElement("table");Object.assign(table.style,{width:"100%",borderCollapse:"collapse",fontSize:"0.78rem",tableLayout:"fixed"});for(const field of fields){const tr=document.createElement("tr"),th=document.createElement("th"),td=document.createElement("td");th.textContent=alias.get(field.name)||field.name;td.textContent=a[field.name]===null||a[field.name]===undefined||a[field.name]===""?"—":String(a[field.name]);Object.assign(th.style,{width:"43%",padding:"6px",borderBottom:"1px solid var(--calcite-color-border-3)",textAlign:"left",verticalAlign:"top",overflowWrap:"anywhere"});Object.assign(td.style,{padding:"6px",borderBottom:"1px solid var(--calcite-color-border-3)",verticalAlign:"top",overflowWrap:"anywhere"});tr.append(th,td);table.append(tr)}section.append(heading,table);wrap.append(section)}mount.replaceChildren(wrap);openPanel()};document.addEventListener("capacity-show-attributes",render);app.onCleanup(()=>{document.removeEventListener("capacity-show-attributes",render);mount.replaceChildren()});return{attributePanel:true,fields:fields.length,records:records.length}}